from lib import *
S = SS('e2')
steps = [
    step("一条 products 记录的 JSON 字节怎么构成(2 万条,紧凑 JSON Lines,逐个记号统计,合计 7194162 字节,与实际字节数相等):字符串值(含引号)4262748 字节占 59.3%;键名(含引号)1880000 字节占 26.1%(每条记录 13 个键,共 94 字节);结构标点(花括号、方括号、逗号、冒号)640000 字节占 8.9%;数字文本 411414 字节占 5.7%。字段名在每一条里重复一遍,占了四分之一多,这是后面“改数组”“列式”和压缩要利用的。", t=tl(S(1)), done=lidx(S(1), '字符串值(含引号)'), mark=lidx(S(1), '键名(含引号)'), b=bars([['字符串值', 59.3, '59.3%'], ['键名', 26.1, '26.1%'], ['结构标点', 8.9, '8.9%'], ['数字文本', 5.7, '5.7%']], 60, mark=[1], done=[0]), kv=KV([['字符串值', '4262748 字节(59.3%)'], ['键名', '1880000 字节(26.1%),每条 94 字节'], ['数字文本', '只占 5.7%']], ['键名'])),
    step("数字的文本长度:price(两位小数的浮点)平均 4.92 字节(3–7),二进制 float64 是 8 字节;stock(0–500 的整数)平均 2.78 字节,16 位二进制是 2 字节;id(7 位整数)恒 7 字节,32 位二进制是 4 字节;timeseries 的 value 平均 5.89 字节,float64 是 8 字节。位数少的数字,文本比定长二进制还短;位数多的整数,文本更长。浮点的文本表示:0.1+0.2 写成 0.30000000000000004(17 位),0.1 写成 0.1,1e22 写成 1e+22。", t=tl(S(2)), done=lidx(S(2), 'price'), mark=lidx(S(2), 'id(7 位整数)'), b=bars([['price 文本平均', 4.92, '4.92'], ['price 二进制', 8, '8'], ['id 文本', 7.00, '7'], ['id 二进制(32 位)', 4, '4']], 9, done=[0], mark=[2]), kv=KV([['price', '文本 4.92 字节 < float64 8 字节'], ['id(7 位)', '文本 7 字节 > 32 位整数 4 字节'], ['0.1 + 0.2', '写成 17 位 0.30000000000000004']], ['id(7 位)'])),
    step("非 ASCII 与转义:中文 1000 字,UTF-8 原文 3000 字节,JSON ensure_ascii=False 3002 字节(1.00×),ensure_ascii=True 6002 字节(2.00×,每个汉字变成 \\uXXXX 的 6 个字节);含 emoji 的文字 ensure_ascii=True 变成 2402 字节(2.40×,emoji 是一对代理项,12 字节);引号、反斜杠、换行、制表重复 100 次,原文 3400 字节,False 为 3802(1.12×);控制字符 1–31 各 30 次,原文 930 字节,两种设置都是 4982 字节(5.36×,控制字符必须转义成 \\u00XX)。zstd-3 压缩后中文 ensure_ascii=False 51 字节、True 80 字节。", t=tl(S(3)), done=lidx(S(3), '中文 1000 字'), mark=lidx(S(3), '控制字符 1–31'), b=bars([['中文 ensure_ascii=False', 3002, '3002'], ['中文 ensure_ascii=True', 6002, '6002'], ['控制字符 JSON', 4982, '4982']], 6100, done=[0], mark=[1, 2]), kv=KV([['中文 ensure_ascii=True', '2.00×,每字 6 字节'], ['含 emoji', '2.40×'], ['控制字符', '5.36×,转义不可避免']], ['中文 ensure_ascii=True'])),
    step("类型与精度:Python 的 json 往返 2^53+1(9007199254740993)没问题;node 26 的 JSON.parse 把它解析成 9007199254740992,最后一位丢了。float('nan') 在 json.dumps 里写成 NaN、inf 写成 Infinity,node 解析失败(这不是合法 JSON);orjson 把它们写成 null。bytes、set 在两者里都抛 TypeError;datetime 标准库抛 TypeError、orjson 写成 ISO 字符串;整数键 {1:'a'} 标准库写成 {\"1\":\"a\"}、orjson 抛 TypeError;tuple 写成数组。JSON 没有 bytes、集合、日期这些类型,要自己约定怎么表示。", t=tl(S(4)), done=lidx(S(4), 'node 26'), mark=lidx(S(4), 'float("nan")'), b=bars([['Python 往返 2^53+1', 1, '一致'], ['node 解析 2^53+1', 0, '丢精度']], 1.2, done=[0], mark=[1]), kv=KV([['2^53+1 在 node 里', '变成 9007199254740992'], ['NaN / Infinity', '标准库写出,node 解析失败'], ['bytes / set', '都抛 TypeError']], ['2^53+1 在 node 里'])),
    step("序列化和解析速度(products 2 万条整体作为一个 7.2 MB 的 JSON 数组,各取 7 次中位数):json.dumps 40.9 ms(168 MiB/s);orjson.dumps 5.2 ms(1323 MiB/s),约 7.9 倍;json.loads 44.2 ms(156 MiB/s);orjson.loads 20.8 ms(331 MiB/s),约 2.1 倍。orjson 的紧凑输出和标准库紧凑输出字节完全相同。同样的格式,实现不同,速度差几倍——比较格式时要分清是格式的代价还是实现的代价。", t=tl(S(5)), done=lidx(S(5), 'orjson.dumps'), mark=lidx(S(5), 'json.dumps'), b=bars([['json.dumps MiB/s', 168, '168'], ['orjson.dumps MiB/s', 1323, '1323'], ['json.loads MiB/s', 156, '156'], ['orjson.loads MiB/s', 331, '331']], 1350, mark=[0, 2], done=[1, 3]), kv=KV([['dumps', 'orjson 约快 7.9 倍'], ['loads', 'orjson 约快 2.1 倍'], ['输出字节', '与标准库紧凑输出完全相同']], ['dumps'])),
    step("键名重复的代价:同样 2 万条 products,三种写法的字节数。原键名 7214161 字节,zstd-3 后 1331194,gzip-6 后 1484671;键名缩成 1 个字母 6114161 字节,zstd 后 1287104,gzip 后 1459181;每条记录写成数组(表头另存)5314161 字节,zstd 后 1236383,gzip 后 1400570。原始字节分别省下 15.2% 和 26.3%,压缩后只省 3.3% 和 7.1%(zstd-3):重复的键名本来就是压缩器最擅长去掉的东西。", t=tl(S(6)), done=lidx(S(6), '每条记录是数组'), mark=lidx(S(6), '原始字节省下'), b=bars([['原键名 zstd-3', 1331194, '1331194'], ['缩短键名 zstd-3', 1287104, '1287104'], ['改数组 zstd-3', 1236383, '1236383']], 1350000, mark=[0], done=[2]), kv=KV([['原始字节省下', '缩短键名 15.2%,改数组 26.3%'], ['zstd-3 压缩后省下', '缩短键名 3.3%,改数组 7.1%'], ['原因', '重复的键名正是压缩器擅长去掉的']], ['原因'])),
]
A = mkarte('e2', 2, '编码,JSON,字节构成,orjson,浮点,Unicode,大整数,zstd,Python,真实验证,动画演示',
    '量 JSON 的真实开销:2 万条商品记录里键名占 26.1%、字符串值占 59.3%、数字只占 5.7%;中文用 ensure_ascii=True 翻倍;node 会丢 2^53+1 的最后一位;orjson 比标准库快 2 到 8 倍;缩短键名省 15.2% 的原始字节,zstd 压缩后只剩 3.3%。',
    'JSON 是爬虫结果最常见的格式。它的字节都花在哪里,数字、中文、转义、大整数各有什么代价,换更快的实现能快多少?这篇把 JSON 本身量一遍,给后面的格式对比一个基线。',
    [('26.1%', 'products 的 JSON 里键名(含引号)占的字节比例;字符串值占 59.3%,数字只占 5.7%'), ('2.00×', '中文用 ensure_ascii=True 写成 \\uXXXX,字节数是 UTF-8 原文的倍数'), ('15.2% 对 3.3%', '把键名缩成 1 个字母:原始字节省下 15.2%,zstd-3 压缩之后只省下 3.3%')],
    [('字节花在哪', '<p>对 2 万条商品记录逐个记号统计:字符串值 59.3%,键名 26.1%,结构标点 8.9%,数字文本 5.7%。键名每条重复一遍(每条 94 字节),是 JSON 比带 schema 的格式大的主要原因之一;数字在这类数据里占比很小。</p>'),
     ('数字', '<p>JSON 的数字是十进制文本:位数少的数字文本反而比定长二进制短(stock 平均 2.78 字节对 2 字节的 16 位整数相差不大,price 平均 4.92 字节对 8 字节 float64 更短),位数多的整数更长(7 位的 id 文本 7 字节,32 位二进制 4 字节)。浮点数写出来可能很长,比如 0.1+0.2 要 17 位。</p>'),
     ('中文与转义', '<p>ensure_ascii=True(Python 的默认)把每个汉字写成 6 字节的 \\uXXXX,中文文本膨胀到 2 倍,emoji 是 12 字节。关掉它(ensure_ascii=False)和 UTF-8 原文一样大。控制字符不管怎样都要转义成 6 字节。</p>'),
     ('类型与精度', '<p>JSON 没有 bytes、集合、日期等类型;大于 2^53 的整数在 JavaScript(node)里会丢精度;NaN 和 Infinity 不是合法 JSON,标准库会写出来而别的解析器会拒绝。要跨语言交换这类数据,要自己约定表示方法(整数用字符串、bytes 用 base64 等)。</p>'),
     ('实现的速度', '<p>同样是 JSON,orjson 的序列化比标准库快约 7.9 倍、解析快约 2.1 倍,输出字节相同。比较“JSON 对 MessagePack”之类时,先分清速度差是格式造成的还是 Python 实现造成的。</p>'),
     ('键名与压缩', '<p>缩短键名把原始字节省下 15.2%,改成数组省 26.3%;压缩之后只剩 3.3% 和 7.1%。重复的键名是压缩器最容易去掉的内容。这也解释了为什么“JSON 压缩后”常常和更紧凑的格式差距不大(见第 20 篇)。</p>')],
    steps,
    [ENV_E + '。数据集见第 1 篇;orjson 3.13.0 临时安装;node v26.10.0 用来看 JSON.parse 的行为;第一到四、六节是确定性结果(各一次),第五节是各 7 次取中位数的计时',
     '没有验证:ujson、simdjson 等其它 JSON 实现;JSON5、JSON Lines 之外的变体;流式解析大 JSON 的内存占用;浮点数“最短表示”算法(只看了输出,没读实现);Windows 或 Linux 上的数字;其它语言(Go、Java)的 JSON 库速度'],
    'JSON 的开销')
